# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ORUÇ VE KUR\'AN AYI RAMAZAN (DKAB.6.2.1)</text>\n  <rect x="25" y="55" width="310" height="180" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="180" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#1d4ed8">Kur\'an Ayı Ramazan</text>\n  <text x="180" y="110" text-anchor="middle" font-size="12" fill="#1e3a8a">• Kur\'an-ı Kerim bu ayda indirilmeye başlanmıştır.</text>\n  <text x="180" y="138" text-anchor="middle" font-size="12" fill="#1e3a8a">• Kadir Gecesi bin aydan daha hayırlıdır.</text>\n  <text x="180" y="166" text-anchor="middle" font-size="12" fill="#1e3a8a">• Cebrail (a.s.) ile Peygamberimizin karşılıklı</text>\n  <text x="180" y="186" text-anchor="middle" font-size="12" fill="#1e3a8a">Kur\'an okuması «Mukabele» geleneğini başlatmıştır.</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Bakara Suresi, 185. Ayet</text>\n  <rect x="365" y="55" width="310" height="180" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="80" text-anchor="middle" font-size="14" font-weight="bold" fill="#15803d">Oruç ve Sabır Ayı Ramazan</text>\n  <text x="520" y="110" text-anchor="middle" font-size="12" fill="#14532d">• Hicri takvimin 9. ayıdır (Kameri ay).</text>\n  <text x="520" y="138" text-anchor="middle" font-size="12" fill="#14532d">• Oruç tutmak bu ayda farz kılınmıştır.</text>\n  <text x="520" y="166" text-anchor="middle" font-size="12" fill="#14532d">• İradeyi güçlendirir, sabrı ve şükrü öğretir.</text>\n  <text x="520" y="194" text-anchor="middle" font-size="12" fill="#14532d">• Paylaşma, yardımlaşma ve merhamet ayıdır.</text>\n  <text x="520" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">Bakara Suresi, 183. Ayet</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ORUÇ İBADETİNİN GÜNLÜK ZAMAN ÇİZELGESİ VE KAVRAMLARI</text>\n  <line x1="60" y1="120" x2="640" y2="120" stroke="#64748b" stroke-width="3"/>\n  <circle cx="110" cy="120" r="10" fill="#3b82f6"/>\n  <circle cx="270" cy="120" r="10" fill="#ef4444"/>\n  <circle cx="430" cy="120" r="10" fill="#22c55e"/>\n  <circle cx="590" cy="120" r="10" fill="#8b5cf6"/>\n  <rect x="40" y="50" width="140" height="52" rx="6" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="110" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">1. SAHUR</text>\n  <text x="110" y="90" text-anchor="middle" font-size="11" fill="#334155">İmsaktan önceki vakit</text>\n  <rect x="200" y="140" width="140" height="65" rx="6" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="270" y="162" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">2. İMSAK</text>\n  <text x="270" y="180" text-anchor="middle" font-size="11" fill="#334155">Oruca başlama anı</text>\n  <text x="270" y="196" text-anchor="middle" font-size="10" fill="#7f1d1d">(Tan yerinin ağarması)</text>\n  <rect x="360" y="50" width="140" height="52" rx="6" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="430" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">3. İFTAR</text>\n  <text x="430" y="90" text-anchor="middle" font-size="11" fill="#334155">Akşam ezanıyla açma</text>\n  <rect x="520" y="140" width="140" height="65" rx="6" fill="#f3e8ff" stroke="#8b5cf6"/>\n  <text x="590" y="162" text-anchor="middle" font-size="13" font-weight="bold" fill="#6d28d9">4. TERAVİH</text>\n  <text x="590" y="180" text-anchor="middle" font-size="11" fill="#334155">Yatsıdan sonra kılınan</text>\n  <text x="590" y="196" text-anchor="middle" font-size="10" fill="#581c87">sünnet namaz (20 rekat)</text>\n  <text x="350" y="238" text-anchor="middle" font-size="12" font-weight="bold" fill="#475569">İmsak ile İftar Arası: Yeme, içme ve kötülüklerden uzak durulan ORUÇ süresi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="30" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">RAMAZAN KÜLTÜRÜ VE YARDIMLAŞMA KAVRAMLARI</text>\n  <rect x="25" y="55" width="205" height="180" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="127" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Kadir Gecesi</text>\n  <text x="127" y="110" text-anchor="middle" font-size="11" fill="#713f12">• Kur\'an\'ın indirildiği gecedir.</text>\n  <text x="127" y="135" text-anchor="middle" font-size="11" fill="#713f12">• «Bin aydan daha hayırlıdır.»</text>\n  <text x="127" y="160" text-anchor="middle" font-size="11" fill="#713f12">• Ramazan\'ın son on günündeki</text>\n  <text x="127" y="178" text-anchor="middle" font-size="11" fill="#713f12">tekli gecelerde aranır.</text>\n  <text x="127" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Kadir Suresi, 1-5. Ayetler</text>\n  <rect x="247" y="55" width="205" height="180" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="350" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Mukabele ve Hatim</text>\n  <text x="350" y="110" text-anchor="middle" font-size="11" fill="#164e63">• Hatim: Kur\'an\'ı baştan sona</text>\n  <text x="350" y="128" text-anchor="middle" font-size="11" fill="#164e63">okuyup tamamlamaktır.</text>\n  <text x="350" y="155" text-anchor="middle" font-size="11" fill="#164e63">• Mukabele: Bir kişinin okuyup</text>\n  <text x="350" y="173" text-anchor="middle" font-size="11" fill="#164e63">diğerlerinin Mushaf\'tan</text>\n  <text x="350" y="191" text-anchor="middle" font-size="11" fill="#164e63">takip etmesi geleneğidir.</text>\n  <rect x="470" y="55" width="205" height="180" rx="8" fill="#fdf2f8" stroke="#ec4899" stroke-width="1.5"/>\n  <text x="572" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Fitre (Sadaka-i Fıtır)</text>\n  <text x="572" y="110" text-anchor="middle" font-size="11" fill="#831843">• Ramazan ayına kavuşmanın</text>\n  <text x="572" y="128" text-anchor="middle" font-size="11" fill="#831843">şükrü olarak verilir.</text>\n  <text x="572" y="155" text-anchor="middle" font-size="11" fill="#831843">• Bayram namazından önce</text>\n  <text x="572" y="173" text-anchor="middle" font-size="11" fill="#831843">ihtiyaç sahiplerine ulaştırılan</text>\n  <text x="572" y="191" text-anchor="middle" font-size="11" fill="#831843">vacip bir sadakadır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
